import requests, datetime

def downstream_impact(table: str) -> list[str]:
    # Query OpenLineage/Marquez for downstream consumers of a table
    r = requests.get(
        "http://marquez:5000/api/v1/lineage",
        params={"nodeId": f"dataset:snowflake:{table}", "depth": 10},
        timeout=10,
    )
    nodes = r.json().get("graph", [])
    return [n["id"] for n in nodes if n["type"] == "DATASET" and n["id"] != table]

def severity(consumers: list[str]) -> str:
    critical = {"exec_revenue_dashboard", "pricing_features", "finance_mart"}
    if any(c.split(":")[-1] in critical for c in consumers):
        return "SEV1"
    if len(consumers) > 10:
        return "SEV2"
    return "SEV3"

def handle_check_failure(table: str, check: str, metric: str):
    consumers = downstream_impact(table)
    sev = severity(consumers)
    detected_at = datetime.datetime.utcnow().isoformat()

    # 1) Page the on-call (PagerDuty Events API v2)
    requests.post("https://events.pagerduty.com/v2/enqueue", json={
        "routing_key": "<PD_ROUTING_KEY>",
        "event_action": "trigger",
        "payload": {
            "summary": f"[{sev}] {check} failed on {table} ({metric})",
            "severity": "critical" if sev == "SEV1" else "error",
            "source": table, "component": "data-pipeline",
            "custom_details": {"downstream": consumers, "detected_at": detected_at},
        },
    }, timeout=10)

    # 2) Open an incident channel with roles pre-assigned
    requests.post("https://slack.com/api/conversations.create",
        headers={"Authorization": "Bearer <SLACK_TOKEN>"},
        json={"name": f"inc-{detected_at[:10]}-{table[:12]}"}, timeout=10)

    return {"severity": sev, "blast_radius": len(consumers),
            "consumers": consumers, "detected_at": detected_at}

if __name__ == "__main__":
    print(handle_check_failure("orders_revenue_mart", "distribution_anomaly", "revenue_p99=100x"))
